declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\Holder\UserConsentedScopesIpAddressAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentedScopesIpAddressAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserConsentedScopesIpAddressAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getIpAddress returns null on a freshly created holder.
     */
    public function testIpAddressNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesIpAddressAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isIpAddressAssigned());
        $this->assertNull($holder->getIpAddress());
    }
}
class ImplWithUserConsentedScopesIpAddressAttributeHolderUnitTest
{
    use UserConsentedScopesIpAddressAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedIpAddressRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultIpAddress();
    }
}
